    insert into tenants (slug, name) values ('kmar', 'KMar');
    insert into doelenbomen (tenant_id, slug, name)
    insert into users (email, password_hash, is_sysadmin)
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'OB1.1', 'Operationele benefit', 'Kritieke processen blijven beschikbaar', 'De voor Bewaken & Beveiligen kritieke operationele processen kunnen bij verstoringen, crises en andere buitengewone omstandigheden binnen de afgesproken continuïteitseisen worden voortgezet of tijdig worden hervat. Hiervoor zijn afhankelijkheden, minimale voorzieningen, uitwijk- en fallbackmogelijkheden en verantwoordelijkheden bekend en georganiseerd.', 'B1.1', '% kritieke processen binnen vastgestelde MTPD/RTO', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'OB1.2', 'Operationele benefit', 'Uitwijk & fallback operationeel inzetbaar', 'Voor kritieke B&B-processen zijn passende uitwijk- en fallbackvoorzieningen beschikbaar, voorbereid en daadwerkelijk bruikbaar. Medewerkers weten wanneer en hoe deze voorzieningen worden ingezet en de werking ervan wordt periodiek beproefd.', 'B1.1', '% kritieke processen met aantoonbaar werkende en geteste uitwijk/fallback', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'OB1.3', 'Operationele benefit', 'Kwetsbaarheden belangen beheerst', 'Kwetsbaarheden rond te beveiligen personen, objecten en andere belangen worden tijdig herkend, beoordeeld en waar mogelijk beheerst, zodat verstoringen of dreigingen minder snel leiden tot uitval of verlies van de beveiligingsfunctie.', 'B1.2', '% kritieke kwetsbaarheden met tijdig uitgevoerde beheersmaatregel', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'OB2.1', 'Operationele benefit', 'Eenduidige besluitvorming & escalatie', 'Binnen B&B is duidelijk wie waarover besluit, welke mandaten gelden en wanneer en naar welk niveau wordt geëscaleerd. Hierdoor kunnen besluiten tijdig, navolgbaar en op het juiste niveau worden genomen.', 'B2.1', '% relevante besluittypen met vastgesteld beslisser, criteria en escalatiepad', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'OB2.2', 'Operationele benefit', 'Heldere verantwoordelijkheden & mandaten', 'Rollen, verantwoordelijkheden, bevoegdheden en mandaten binnen de B&B-organisatie en relevante samenwerkingsverbanden zijn expliciet beschreven en worden in de praktijk eenduidig toegepast.', 'B2.1', '% kritieke processen met vastgestelde rol-/mandaatverdeling', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'OB2.3', 'Operationele benefit', 'Gestandaardiseerde operationele processen', 'De belangrijkste operationele B&B-processen zijn waar zinvol geharmoniseerd en gestandaardiseerd, waardoor uitvoering minder persoons- of locatieafhankelijk wordt en kwaliteit, overdraagbaarheid en bestuurbaarheid toenemen.', 'B2.2', '% kernprocessen vastgesteld én aantoonbaar volgens standaard uitgevoerd', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'OB3.1', 'Operationele benefit', 'Eenheden aantoonbaar gereed', 'Eenheden en medewerkers die voor B&B worden ingezet voldoen aantoonbaar aan de voor hun inzet geldende eisen ten aanzien van personeel, opleiding, middelen, procedures en overige gereedstellingsvoorwaarden.', 'B3.1', '% eenheden dat voldoet aan vastgestelde gereedstellingsnorm', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'OB3.2', 'Operationele benefit', 'Opschaling binnen normtijd', 'Bij een veranderende dreiging, incident, crisis of militaire noodzaak kan B&B binnen de daarvoor gestelde tijd gecontroleerd opschalen naar de benodigde capaciteit en het vereiste niveau van inzet.', 'B3.2', '% opschalingsscenario''s gerealiseerd binnen normtijd', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'OB3.3', 'Operationele benefit', 'Inzetconcepten schaalbaar', 'Operationele inzetconcepten zijn zodanig ingericht dat capaciteit, werkwijze, commandovoering en ondersteuning kunnen worden aangepast aan verschillende dreigings- en inzetsituaties, van vredestijd via hybride omstandigheden tot oorlogssituaties.', 'B3.2', '% relevante scenario''s waarvoor een beproefd schaalbaar inzetconcept beschikbaar is', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'OB4.1', 'Operationele benefit', 'Opleidingen sluiten aan op inzet', 'Opleiding, training en vorming sluiten aantoonbaar aan op de actuele en toekomstige eisen van het B&B-optreden, zodat medewerkers beschikken over de kennis en vaardigheden die zij voor hun taak daadwerkelijk nodig hebben.', 'B4.1', '% kritieke competenties afgedekt door actueel OT&V-aanbod', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'OB4.2', 'Operationele benefit', 'Talent gericht ontwikkeld & behouden', 'Medewerkers worden gericht ontwikkeld op basis van benodigde competenties en toekomstig B&B-vakmanschap. Kennis, ervaring en talent worden zo veel mogelijk voor het domein behouden en doelgericht ingezet.', 'B4.2', '% kritieke functies met voldoende gekwalificeerde bezetting', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'OB4.3', 'Operationele benefit', 'Duurzame inzetbaarheid geborgd', 'De organisatie creëert voorwaarden waardoor medewerkers langdurig verantwoord en effectief inzetbaar blijven, met aandacht voor belasting, ontwikkeling, vakbekwaamheid en continuïteit van de personele capaciteit.', 'B4.2', '% benodigde personele capaciteit duurzaam inzetbaar', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'OB5.1', 'Operationele benefit', 'Innovaties gecontroleerd beproefd', 'Nieuwe technologieën, concepten en werkwijzen worden gecontroleerd en doelgericht in de operationele context beproefd voordat tot bredere toepassing wordt besloten.', 'B5.1', '% innovaties met afgeronde operationele beproeving en evaluatie', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'OB5.2', 'Operationele benefit', 'Lessons learned structureel verwerkt', 'Ervaringen uit operaties, oefeningen, incidenten, evaluaties en experimenten worden systematisch verzameld, beoordeeld en vertaald naar verbeteringen in processen, werkwijzen, opleidingen en voorzieningen.', 'B5.2', '% vastgestelde lessons learned binnen termijn verwerkt', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'OB5.3', 'Operationele benefit', 'Innovaties sneller opgeschaald', 'Innovaties waarvan de meerwaarde aantoonbaar is, kunnen sneller en gecontroleerd worden opgeschaald van experiment of lokale toepassing naar bredere inzet binnen B&B.', 'B5.1', 'Gemiddelde doorlooptijd van bewezen innovatie naar structurele toepassing', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'OB6.1', 'Operationele benefit', 'Betere informatie voor besluitvorming', 'Besluitvormers en operationele functionarissen beschikken tijdig over relevante, betrouwbare en bruikbare informatie om dreigingen, risico''s en operationele situaties te beoordelen en passende besluiten te nemen.', 'B6.1', '% kritieke besluiten waarbij vereiste informatie tijdig beschikbaar is', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'OB6.2', 'Operationele benefit', 'Actueel dreigings- en risicobeeld', 'B&B beschikt over een actueel en samenhangend beeld van relevante dreigingen, risico''s, kwetsbaarheden en ontwikkelingen, zodat maatregelen tijdig kunnen worden aangepast.', 'B6.1', '% afgesproken momenten waarop actueel dreigings-/risicobeeld beschikbaar is', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'OB6.3', 'Operationele benefit', 'Digitale koppelvlakken robuust', 'De digitale informatie-uitwisseling tussen relevante systemen, organisatieonderdelen en ketenpartners is voldoende beschikbaar, veilig en robuust om de operationele informatiebehoefte ook onder verhoogde belasting of verstoring te ondersteunen.', 'B6.2', 'Beschikbaarheid kritieke informatieketens (%)', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'OB7.1', 'Operationele benefit', 'Ketenpartners handelen volgens afspraken', 'Betrokken organisaties kennen en hanteren de gemaakte afspraken over rollen, verantwoordelijkheden, informatie-uitwisseling, besluitvorming en optreden binnen het B&B-stelsel.', 'B7.1', '% kritieke stelselafspraken aantoonbaar operationeel toegepast/beproefd', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'OB7.2', 'Operationele benefit', 'KMar-positie in stelsel duidelijk', 'Voor interne en externe partijen is helder welke positie, verantwoordelijkheid, bevoegdheid en toegevoegde waarde de KMar binnen het stelsel Bewaken & Beveiligen heeft.', 'B7.1', '% relevante stelselprocessen met vastgestelde KMar-rol en mandaat', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'OB7.3', 'Operationele benefit', 'Persoonsgerichte maatregelen afgestemd', 'Maatregelen rondom persoonsgerichte beveiliging worden tussen betrokken partijen samenhangend voorbereid, afgestemd en uitgevoerd, zodat verantwoordelijkheden duidelijk zijn en maatregelen elkaar versterken.', 'B7.2', '% relevante casussen met aantoonbaar afgestemd maatregelenpakket', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'B1.1', 'Sub-benefit', 'Continuïteit kritieke processen', 'Kritieke B&B-processen beschikken over voldoende organisatorische, personele, informatiekundige en materiële continuïteitsvoorzieningen om verstoringen op te vangen en de noodzakelijke dienstverlening voort te zetten.', 'B1', '% kritieke processen dat voldoet aan vastgestelde continuïteitseisen', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'B1.2', 'Sub-benefit', 'Weerbaarheid te beveiligen belangen', 'De bescherming van personen, objecten en andere belangen is beter bestand tegen verstoringen, veranderende dreigingen en uitval van voorzieningen.', 'B1', '% prioritaire belangen met actueel weerbaarheids-/kwetsbaarheidsbeeld', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'B2.1', 'Sub-benefit', 'Heldere governance & rollen', 'Governance, verantwoordelijkheden, bevoegdheden en escalatielijnen zijn zodanig ingericht dat het B&B-domein eenduidig kan worden bestuurd en besluiten op het juiste niveau worden genomen.', 'B2', '% governance-elementen aantoonbaar vastgesteld en werkend', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'B2.2', 'Sub-benefit', 'Operationele bedrijfsvoering op orde', 'De processen, verantwoordelijkheden en ondersteunende voorzieningen die nodig zijn voor de dagelijkse B&B-uitvoering zijn beheerst, voorspelbaar en voldoende gestandaardiseerd.', 'B2', '% kritieke bedrijfsvoeringsprocessen aantoonbaar beheerst', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'B3.1', 'Sub-benefit', 'Gereedstelling op norm', 'Personeel, eenheden, middelen en ondersteunende voorzieningen voldoen aantoonbaar aan vastgestelde eisen voor de beoogde inzet.', 'B3', 'Gereedstellingspercentage t.o.v. vastgestelde norm', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'B3.2', 'Sub-benefit', 'Opschalingsvermogen', 'B&B kan capaciteit en wijze van optreden gecontroleerd aanpassen aan veranderende dreiging en omstandigheden, inclusief opschaling richting hybride en oorlogssituaties.', 'B3', '% beproefde opschalingsscenario''s dat aan norm voldoet', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'B4.1', 'Sub-benefit', 'Actueel OT&V-aanbod', 'Het aanbod voor opleiding, training en vorming sluit structureel aan op de actuele en toekomstige eisen aan het B&B-vakmanschap.', 'B4', '% OT&V-producten binnen afgesproken actualiteitstermijn', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'B4.2', 'Sub-benefit', 'Aantrekkelijke loopbaanpaden', 'Medewerkers beschikken over herkenbare mogelijkheden voor ontwikkeling, specialisatie en doorstroom, waarmee talent kan worden ontwikkeld en behouden.', 'B4', '% kritieke functiegebieden met vastgesteld ontwikkel-/loopbaanpad', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'B5.1', 'Sub-benefit', 'Beproefde innovaties', 'Vernieuwingen zijn niet uitsluitend bedacht of ontwikkeld, maar in een relevante context beproefd en op hun operationele meerwaarde beoordeeld.', 'B5', '% innovatieportfolio met bewezen operationele meerwaarde', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'B5.2', 'Sub-benefit', 'Structureel lerend vermogen', 'B&B beschikt over een structureel mechanisme om ervaringen en nieuwe inzichten te verzamelen, te beoordelen, te delen en om te zetten in verbetering.', 'B5', '% evaluaties waarvan verbeteracties aantoonbaar zijn geborgd', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'B6.1', 'Sub-benefit', 'Sterkere intelligencepositie', 'De informatie- en intelligencepositie ondersteunt een beter en actueler begrip van dreigingen, risico''s en relevante ontwikkelingen ten behoeve van besluitvorming en optreden.', 'B6', '% kritieke informatiebehoeften tijdig ingevuld', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'B6.2', 'Sub-benefit', 'Digitaal weerbare informatievoorziening', 'De informatievoorziening die B&B ondersteunt is beschikbaar, veilig, robuust en voldoende bestand tegen verstoring en digitale dreiging.', 'B6', '% kritieke IV-diensten dat voldoet aan beschikbaarheids- en weerbaarheidseisen', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'B7.1', 'Sub-benefit', 'Werkende stelselafspraken', 'Afspraken tussen KMar en partners binnen het B&B-stelsel zijn helder, toepasbaar en worden in de praktijk daadwerkelijk nageleefd.', 'B7', '% kritieke stelselafspraken succesvol beproefd', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'B7.2', 'Sub-benefit', 'Persoonsgerichte beveiligingsaanpak', 'Persoonsgerichte beveiligingsmaatregelen worden vanuit een samenhangende aanpak georganiseerd en afgestemd tussen de betrokken partijen.', 'B7', '% relevante maatregelen/casussen aantoonbaar integraal afgestemd', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'B1', 'Programmabaat', 'Weerbaarheid & voortzetting', 'FPBB versterkt het vermogen van B&B om kritieke beveiligingstaken onder verstoring en veranderende dreiging te blijven uitvoeren en, wanneer reguliere voorzieningen uitvallen, tijdig passende continuïteitsmaatregelen in te zetten.', 'A1 primair; A2 ondersteunend', 'Samengestelde continuïteits-/weerbaarheidsindex', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'B2', 'Programmabaat', 'Bestuurbaarheid', 'FPBB zorgt voor een B&B-domein dat door heldere governance, rollen, mandaten, besluitvorming en beheerste bedrijfsvoering beter bestuurbaar en voorspelbaar functioneert.', 'A1 primair; A6 ondersteunend', '% kritieke besturingsprocessen aantoonbaar beheerst', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'B3', 'Programmabaat', 'Militair vermogen', 'FPBB versterkt het militaire vermogen binnen B&B door aantoonbare gereedstelling, schaalbare inzetconcepten en het vermogen om bij veranderende omstandigheden tijdig op te schalen.', 'A2 primair; A1 ondersteunend', '% militaire/gereedstellingscriteria aantoonbaar behaald', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'B4', 'Programmabaat', 'Vakmanschap & talent', 'FPBB zorgt dat B&B duurzaam beschikt over vakbekwame, ontwikkelde en inzetbare medewerkers en een omgeving waarin relevant talent kan worden aangetrokken, ontwikkeld en behouden.', 'A5 primair; A3 ondersteunend', '% kritieke competentiebehoefte duurzaam afgedekt', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'B5', 'Programmabaat', 'Innovatie & kwaliteit', 'FPBB versterkt het vermogen om systematisch te leren, kansrijke vernieuwingen gecontroleerd te beproeven en bewezen verbeteringen duurzaam en breder in de uitvoering toe te passen.', 'A3 primair; A1 ondersteunend', '% bewezen verbeteringen aantoonbaar geborgd/opgeschaald', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'B6', 'Programmabaat', 'Informatiepositie', 'FPBB versterkt de informatiepositie van B&B door tijdige en bruikbare informatie, een actueel dreigings- en risicobeeld en een robuuste en digitaal weerbare informatievoorziening.', 'A4 primair; A1/A3 ondersteunend', '% kritieke informatiebehoefte tijdig, juist en beschikbaar', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'B7', 'Programmabaat', 'Stelselsamenwerking', 'FPBB versterkt de samenwerking binnen het B&B-stelsel door duidelijke posities en verantwoordelijkheden, werkende afspraken en beter afgestemde gezamenlijke beveiligingsmaatregelen.', 'A6 primair; A1 ondersteunend', '% kritieke stelselprocessen aantoonbaar volgens gezamenlijke afspraken uitgevoerd', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'A1', 'Strategische benefit', 'Wendbaar & voortzettend', 'B&B is in staat het optreden tijdig aan veranderende omstandigheden aan te passen en de essentiële beveiligingstaken ook bij verstoring, crisis of verhoogde dreiging voort te zetten.', 'S2/S3', 'Strategische effectindicator – nog gezamenlijk definiëren', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'A2', 'Strategische benefit', 'Militair vermogen', 'B&B levert een herkenbare en aantoonbare bijdrage aan het militaire vermogen van de KMar en kan passend functioneren onder omstandigheden waarin militaire gereedheid, schaalbaarheid en optreden noodzakelijk zijn.', 'S1/S2/S5', 'Strategische gereedheidsindicator – nog definiëren', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'A3', 'Strategische benefit', 'Innovatief & hoogwaardig', 'B&B ontwikkelt en benut hoogwaardige kennis, werkwijzen en innovaties om de kwaliteit en effectiviteit van het optreden duurzaam te verbeteren.', 'S1/S3/S5', 'Strategische kwaliteits-/innovatie-indicator – nog definiëren', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'A4', 'Strategische benefit', 'Informatiegestuurd optreden', 'B&B gebruikt relevante, betrouwbare en actuele informatie structureel om dreigingen te begrijpen, keuzes te onderbouwen en het operationele optreden gericht te sturen.', 'S1/S3/S4', '% kritieke besluiten aantoonbaar informatiegestuurd onderbouwd', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'A5', 'Strategische benefit', 'Aantrekkelijk werkgever', 'Het B&B-domein biedt een professionele werkomgeving waarin medewerkers zich kunnen ontwikkelen, vakmanschap wordt gewaardeerd en relevante medewerkers en talenten worden aangetrokken en behouden.', 'S1/S5', 'Vullings-/behoud-/vakbekwaamheidsindicator – nog definiëren', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'A6', 'Strategische benefit', 'Partner & beschermer', 'De KMar vervult binnen B&B een duidelijke en betrouwbare rol als partner en beschermer en werkt effectief samen met andere partijen om gezamenlijke beveiligingsdoelen te realiseren.', 'S1/S3', 'Strategische samenwerkingsindicator – nog definiëren', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'S1', 'Strategisch doel', 'Krachtige uitvoerder', 'De KMar beschikt over het vermogen, de mensen, middelen, informatie en samenwerkingsrelaties om haar opgedragen taken effectief, professioneel en betrouwbaar uit te voeren.', 'Missie', 'Niet door FPBB zelfstandig als KPI vaststellen', '', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'S2', 'Strategisch doel', 'Robuust & weerbaar gendarmeriekorps', 'De KMar is organisatorisch en operationeel voldoende robuust en weerbaar om haar taken ook onder verstoring, verhoogde dreiging en buitengewone omstandigheden te blijven uitvoeren.', 'Missie', 'Organisatiebrede KMar-indicator gebruiken', '', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'S3', 'Strategisch doel', 'Strategisch wendbaar', 'De KMar kan tijdig anticiperen op veranderingen in dreiging, omgeving, opdracht en maatschappelijke context en haar organisatie en optreden daarop aanpassen.', 'Missie', 'Organisatiebrede KMar-indicator gebruiken', '', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'S4', 'Strategisch doel', 'Datagedreven organisatie', 'De KMar benut data en informatie structureel en verantwoord voor analyse, besluitvorming, sturing en verbetering van de uitvoering.', 'Missie', 'Organisatiebrede KMar-indicator gebruiken', '', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'S5', 'Strategisch doel', 'Schaalbaarheid & kwaliteit', 'De KMar kan capaciteit en optreden gecontroleerd op- en afschalen en borgt daarbij de vereiste kwaliteit en professionaliteit van de taakuitvoering.', 'Missie', 'Organisatiebrede KMar-indicator gebruiken', '', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'M1', 'Missie', 'Veiligheid van de Staat en beveiliging van belangen van nationaal belang', 'De KMar staat voor de veiligheid van de Staat en de beveiliging van objecten, subjecten en diensten van nationaal belang met een hoog afbreukrisico. Deze missie vormt het hoogste anker van de Benefits Logic Map: alle onderliggende doelen, benefits en programmabaten moeten uiteindelijk aantoonbaar bijdragen aan deze bedoeling.', '', '-', '', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'C1', 'Capability', 'Continuïteitsmanagement B&B', 'Vermogen om kritieke processen, afhankelijkheden, continuïteitseisen en herstelprioriteiten structureel te bepalen, vast te leggen, te onderhouden en te beheersen.', 'OB1.1; OB1.2; OB1.3', 'Volwassenheid continuïteitsmanagement / % kritieke processen met actuele continuïteitseisen', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'C2', 'Capability', 'Continuïteit operationele inzet', 'Vermogen om de operationele B&B-taak tijdens verstoring binnen afgesproken grenzen voort te zetten of tijdig te herstellen, inclusief het organiseren van minimale bezetting, middelen, informatie en werkwijzen.', 'OB1.1; OB1.2', '% kritieke operationele functies dat binnen continuïteitsnorm kan blijven functioneren', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'C3', 'Capability', 'Uitwijk- & fallbackvermogen', 'Vermogen om bij uitval van reguliere voorzieningen gecontroleerd over te schakelen op alternatieve locaties, informatievoorziening, middelen, capaciteit en werkwijzen.', 'OB1.2; OB1.1', '% kritieke processen met aantoonbaar inzetbare uitwijk- of fallbackvoorziening', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'C4', 'Capability', 'Continuïteitsbeproeving', 'Vermogen om continuïteits-, uitwijk-, fallback- en herstelscenario''s periodiek door middel van oefeningen, tests en evaluaties aantoonbaar te valideren en te verbeteren.', 'OB1.2; OB1.1; OB3.2', '% kritieke continuïteitsscenario''s periodiek succesvol beproefd', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'C5', 'Capability', 'Weerbaarheids- & kwetsbaarheidsmanagement', 'Vermogen om kwetsbaarheden van te beveiligen belangen systematisch te identificeren, analyseren, prioriteren, beheersen en periodiek te herijken.', 'OB1.3; OB1.1', '% prioritaire belangen met actueel kwetsbaarheids- en maatregelenbeeld', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'C6', 'Capability', 'Operationele command & control', 'Vermogen om operationele besluitvorming, sturing, coördinatie en escalatie onder reguliere en bijzondere omstandigheden eenduidig en tijdig te organiseren.', 'OB2.1; OB2.2; OB3.2', '% relevante scenario''s waarin command & control volgens norm functioneert', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'C7', 'Capability', 'Governance & besluitvorming B&B', 'Vermogen om bestuurlijke besluitvorming, rollen, mandaten, verantwoordelijkheden en escalatieniveaus structureel in te richten, toe te passen en te onderhouden.', 'OB2.1; OB2.2; OB7.2', '% kritieke governance-elementen vastgesteld en aantoonbaar werkend', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'C8', 'Capability', 'Procesmanagement B&B', 'Vermogen om operationele en ondersteunende B&B-processen te ontwerpen, standaardiseren, beheren, meten en continu te verbeteren.', 'OB2.3; OB2.1; OB2.2', '% kritieke processen vastgesteld, beheerd en aantoonbaar volgens standaard uitgevoerd', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'C9', 'Capability', 'Gereedstellingsmanagement', 'Vermogen om gereedheidseisen vast te stellen en aantoonbaar te maken dat personeel, materieel, opleiding, ondersteuning en procedures hieraan voldoen.', 'OB3.1; OB3.2; OB3.3', '% eenheden/capaciteiten dat voldoet aan vastgestelde gereedstellingsnorm', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'C10', 'Capability', 'Gereedheidsinformatie', 'Vermogen om actueel, betrouwbaar en bruikbaar inzicht te geven in de feitelijke gereedheid, beschikbaarheid en inzetbaarheid van personeel, materieel en ondersteunende voorzieningen.', 'OB3.1; OB3.2; OB6.1', '% kritieke gereedheidsinformatie tijdig en actueel beschikbaar', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'C11', 'Capability', 'Operationeel opschalingsvermogen', 'Vermogen om personeel, middelen, commandovoering en ondersteuning binnen vastgestelde termijnen gecontroleerd op te schalen en weer af te schalen.', 'OB3.2; OB3.3', '% opschalingsscenario''s binnen normtijd gerealiseerd', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'C12', 'Capability', 'Capaciteitsmanagement', 'Vermogen om benodigde en beschikbare capaciteit vooruit te voorspellen, plannen, alloceren, monitoren en bij veranderende prioriteiten bij te sturen.', 'OB3.2; OB3.1; OB4.3', '% capaciteitsbehoefte tijdig gedekt / afwijking behoefte versus beschikbaarheid', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'C13', 'Capability', 'Ontwikkeling & beheer inzetconcepten', 'Vermogen om inzetconcepten voor verschillende dreigings- en inzetsituaties te ontwikkelen, vast te stellen, te onderhouden, te beproeven en operationeel toepasbaar te houden.', 'OB3.3; OB3.2', '% relevante scenario''s met vastgesteld en beproefd inzetconcept', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'C14', 'Capability', 'Competentiegericht OT&V', 'Vermogen om opleiding, training en vorming structureel te ontwerpen en actualiseren vanuit benodigde operationele competenties en toekomstige inzetprofielen.', 'OB4.1; OB3.1; OB4.2', '% kritieke competenties aantoonbaar afgedekt door actueel OT&V-aanbod', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'C15', 'Capability', 'Strategisch talent- & competentiemanagement', 'Vermogen om de toekomstige behoefte aan competenties en talent te identificeren en medewerkers gericht aan te trekken, ontwikkelen, inzetten en behouden.', 'OB4.2; OB3.1; OB4.1; OB4.3', '% kritieke competentiebehoefte duurzaam afgedekt', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'C16', 'Capability', 'Loopbaan- & ontwikkelmanagement', 'Vermogen om herkenbare ontwikkel-, specialisatie- en loopbaanpaden voor medewerkers binnen B&B te ontwerpen, onderhouden en toepassen.', 'OB4.2; OB4.3', '% kritieke functiegebieden met vastgesteld ontwikkel- en loopbaanpad', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'C17', 'Capability', 'Duurzame personele inzetbaarheid', 'Vermogen om de fysieke, mentale en professionele inzetbaarheid van B&B-personeel structureel te ondersteunen en langdurig op het benodigde niveau te houden.', 'OB4.3; OB4.2', '% benodigde personele capaciteit duurzaam inzetbaar', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'C18', 'Capability', 'Innovatie- & experimenteervermogen', 'Vermogen om nieuwe technologieën, concepten en werkwijzen gecontroleerd te ontwikkelen, experimenteren, beproeven en op operationele meerwaarde te beoordelen.', 'OB5.1; OB5.2; OB5.3', '% innovaties met afgeronde beproeving en gevalideerde operationele meerwaarde', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'C19', 'Capability', 'Leren & verbeteren', 'Vermogen om ervaringen uit inzet, oefeningen, incidenten, audits en evaluaties systematisch te verzamelen, analyseren en te vertalen naar aantoonbare verbeteringen.', 'OB5.2; OB2.3; OB4.1; OB5.1; OB5.3', '% vastgestelde lessons learned binnen normtermijn verwerkt en geborgd', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'C20', 'Capability', 'Innovatie-implementatie & opschaling', 'Vermogen om bewezen innovaties gecontroleerd van experiment of lokale toepassing naar structurele en bredere toepassing binnen B&B te brengen.', 'OB5.3; OB5.1; OB5.2', 'Gemiddelde doorlooptijd van bewezen innovatie naar structurele toepassing', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'C21', 'Capability', 'Operationele informatievoorziening', 'Vermogen om relevante, betrouwbare, actuele en tijdige informatie beschikbaar te stellen aan operationele en bestuurlijke besluitvormers.', 'OB6.1; OB2.1; OB3.1; OB3.2; OB6.2', '% kritieke informatiebehoeften tijdig, juist en bruikbaar ingevuld', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'C22', 'Capability', 'Informatiegestuurd optreden', 'Vermogen om informatie en intelligence structureel te vertalen naar handelingsperspectief, prioritering, besluitvorming en operationele sturing.', 'OB6.1; OB2.1; OB6.2', '% kritieke besluiten aantoonbaar informatiegestuurd onderbouwd', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'C23', 'Capability', 'Intelligence & dreigingsbeeld', 'Vermogen om relevante informatie te verzamelen, analyseren, duiden en te integreren tot een actueel en bruikbaar dreigings- en risicobeeld.', 'OB6.2; OB1.3; OB6.1; OB7.3', '% afgesproken momenten waarop actueel en gevalideerd dreigingsbeeld beschikbaar is', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'C24', 'Capability', 'Risicomanagement B&B', 'Vermogen om operationele en beveiligingsrisico''s systematisch te identificeren, beoordelen, prioriteren, vertalen naar maatregelen en te monitoren.', 'OB1.3; OB1.1; OB6.1; OB6.2', '% prioritaire risico''s met actuele beoordeling, eigenaar en beheersmaatregel', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'C25', 'Capability', 'Digitale informatie-uitwisseling', 'Vermogen om informatie veilig, betrouwbaar, tijdig en gestandaardiseerd tussen relevante systemen, organisatieonderdelen en ketenpartners uit te wisselen.', 'OB6.3; OB6.1; OB6.2; OB7.1; OB7.3', 'Beschikbaarheid en succesvolle gegevensuitwisseling kritieke digitale koppelvlakken (%)', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'C26', 'Capability', 'Digitale weerbaarheid B&B', 'Vermogen om kritieke informatievoorziening beschikbaar, veilig, redundant en herstelbaar te houden bij verstoring, cyberdreiging en verhoogde belasting.', 'OB6.3; OB6.2; OB1.1', '% kritieke IV-diensten dat voldoet aan beschikbaarheids- en weerbaarheidseisen', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'C27', 'Capability', 'Stelsel- & ketenregie', 'Vermogen om afspraken, afhankelijkheden, verantwoordelijkheden en gezamenlijke werkwijzen tussen betrokken organisaties structureel te organiseren, coördineren en bewaken.', 'OB7.1; OB7.2; OB2.1; OB2.2; OB7.3', '% kritieke stelselafspraken aantoonbaar werkend en periodiek getoetst', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'C28', 'Capability', 'Interorganisationele samenwerking', 'Vermogen om met keten- en stelselpartners operationeel effectief samen te werken, informatie te delen, gezamenlijke besluiten te nemen en geïntegreerd op te treden.', 'OB7.1; OB7.3; OB7.2', '% relevante samenwerkingsscenario''s succesvol gezamenlijk uitgevoerd/beproefd', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'C29', 'Capability', 'Positionering & rolvastheid KMar B&B', 'Vermogen om de rol, verantwoordelijkheid, bevoegdheden en toegevoegde waarde van de KMar binnen het B&B-stelsel eenduidig te definiëren, uit te dragen en in de praktijk rolvast uit te oefenen.', 'OB7.2; OB7.1', '% relevante stelselprocessen met vastgestelde en herkenbaar toegepaste KMar-rol', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'C30', 'Capability', 'Persoonsgerichte beveiliging', 'Vermogen om persoonsgerichte beveiligingsmaatregelen integraal te ontwerpen, af te stemmen, uit te voeren, te evalueren en bij gewijzigde dreiging tijdig bij te stellen.', 'OB7.3; OB1.3; OB6.2', '% relevante persoonsgerichte casussen met integraal afgestemd en geëvalueerd maatregelenpakket', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'C31', 'Capability', 'Technische sweepcapaciteit', 'Het duurzame vermogen om voertuigen en andere relevante objecten planmatig, deskundig, veilig en herhaalbaar technisch te controleren op ongewenste voorzieningen die observatie, plaatsbepaling, registratie of afluisteren mogelijk maken, bevindingen te duiden en passende vervolgmaatregelen te initiëren.', 'OB1.4; OB1.3; OB6.2', 'Beschikbaarheid gekwalificeerde sweepcapaciteit; % relevante controles volgens vastgesteld regime; doorlooptijd aanleiding tot sweep', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'OB1.4', 'Operationele benefit', 'Technische compromittering tijdig gedetecteerd en beheerst', 'Ongewenste technische voorzieningen waarmee voertuigen, personen of andere relevante belangen kunnen worden gevolgd, gelokaliseerd, geregistreerd of afgeluisterd worden tijdig gedetecteerd, beoordeeld en volgens een vastgestelde werkwijze beheerst, zodat de potentiële impact op beveiliging en informatiepositie wordt beperkt.', 'B1.2', '% relevante sweepaanleidingen binnen normtijd uitgevoerd; % bevindingen volgens procedure geduid en afgehandeld', 'Bewaken & Beveiligen', '');
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld) values ((select id from doelenbomen where slug='fpbb'), 'NP01', 'Project', 'Business Continuity Management (BCM)', 'Integraal BCM-systeem voor kritieke B&B-processen, BIA’s, afhankelijkheden, maximale uitvalduur en herstelprioriteiten.', 'C1; C2', 'Projectvoortgang en oplevercriteria volgens het betreffende PID', 'Bewaken & Beveiligen', '');
